-- Forward-fix retained because remote smoke testing found an output-column ambiguity.
create or replace function public.complete_my_onboarding(p_date_of_birth date,p_terms_version text,p_community_rules_version text,p_age_verification_method text default 'self_declared') returns table(user_id uuid,age_verified boolean,account_status text,completed_at timestamptz) language plpgsql security definer set search_path='' as $$declare v_user_id uuid:=(select auth.uid()); v_now timestamptz:=now(); v_existing_dob date; v_method private.age_verification_method; begin if v_user_id is null then raise exception using errcode='28000',message='authentication required'; end if; if p_date_of_birth is null or p_date_of_birth>current_date then raise exception using errcode='22008',message='invalid date_of_birth'; end if; if p_date_of_birth>(current_date-interval '18 years')::date then raise exception using errcode='22023',message='user must be at least 18 years old'; end if; if p_age_verification_method not in('self_declared','document','manual_review','third_party') then raise exception using errcode='22023',message='invalid age verification method'; end if; v_method:=p_age_verification_method::private.age_verification_method; select ui.date_of_birth into v_existing_dob from private.user_identity ui where ui.user_id=v_user_id; if v_existing_dob is not null and v_existing_dob<>p_date_of_birth then raise exception using errcode='22023',message='verified date_of_birth cannot be changed by client'; end if; if nullif(btrim(p_terms_version),'') is null or char_length(p_terms_version)>64 then raise exception using errcode='22023',message='invalid terms version'; end if; if nullif(btrim(p_community_rules_version),'') is null or char_length(p_community_rules_version)>64 then raise exception using errcode='22023',message='invalid community rules version'; end if; insert into private.user_identity(user_id,date_of_birth,age_verified_at,age_verification_method,terms_version,terms_accepted_at,community_rules_version,community_rules_accepted_at,account_status) values(v_user_id,p_date_of_birth,v_now,v_method,btrim(p_terms_version),v_now,btrim(p_community_rules_version),v_now,'active'::private.account_status) on conflict on constraint user_identity_pkey do update set date_of_birth=excluded.date_of_birth,age_verified_at=excluded.age_verified_at,age_verification_method=excluded.age_verification_method,terms_version=excluded.terms_version,terms_accepted_at=excluded.terms_accepted_at,community_rules_version=excluded.community_rules_version,community_rules_accepted_at=excluded.community_rules_accepted_at,account_status='active'::private.account_status,suspension_reason_code=null; return query select v_user_id,true,'active'::text,v_now; end;$$;
revoke all on function public.complete_my_onboarding(date,text,text,text) from public,anon;
grant execute on function public.complete_my_onboarding(date,text,text,text) to authenticated,service_role;
